def keep_latest_future_projection_report_per_user(apps, schema_editor):
    """Mantem so a linha mais recente por usuario antes de exigir unicidade.

    `FutureProjectionReport.user` deixa de ser uma FK com historico e passa a
    ser `OneToOneField` (reanalisar substitui, nao acumula) -- linhas antigas
    de um mesmo usuario violariam a constraint de unicidade que a proxima
    operacao adiciona.
    """
    FutureProjectionReport = apps.get_model("finance", "FutureProjectionReport")
    seen_users = set()
    for report in FutureProjectionReport.objects.order_by("user_id", "-created_at"):
        if report.user_id in seen_users:
            report.delete()
        else:
            seen_users.add(report.user_id)


